    $WaitForFile $Path;
  } do={
    $LogPrint warning $0 ("Making directory '" . $Path . "' failed: " . $Err);
    :return false;
  }

  :return true;
}

# return an IPv4 netmask for CIDR
:set NetMask4 do={
  :local CIDR [ :tonum $1 ];

  :return ((255.255.255.255 << (32 - $CIDR)) & 255.255.255.255);
}

# return an IPv6 netmask for CIDR
:set NetMask6 do={
  :local CIDR [ :tostr $1 ];

  :global IfThenElse;
  :global MAX;
  :global MIN;

  :global NetMask6Cache;

  :if ([ :typeof ($NetMask6Cache->$CIDR) ] = "ip6") do={
    :return ($NetMask6Cache->$CIDR);
  }

  :if ([ :typeof $NetMask6Cache ] = "nothing") do={
    :set NetMask6Cache ({});
  }

  :local Mask "";
  :for I from=0 to=7 do={
    :set Mask ($Mask . \
      [ :convert from=num to=hex (0xffff - (0xffff >> [ :tonum [ $MIN [ $MAX ($CIDR - (16 * $I)) 0 ] 16 ] ])) ] . \
      [ $IfThenElse ($I < 7) ":" ]);
  }
  :set Mask [ :toip6 $Mask ];
  :set ($NetMask6Cache->$CIDR) $Mask;
  :return $Mask;
}

# prepare NotificationFunctions array
:if ([ :typeof $NotificationFunctions ] != "array") do={
  :set NotificationFunctions ({});
}

# parse the date and return a named array
:set ParseDate do={
  :local Date [ :tostr $1 ];

  :return ({ "year"=[ :tonum [ :pick $Date 0 4 ] ];
            "month"=[ :tonum [ :pick $Date 5 7 ] ];
              "day"=[ :tonum [ :pick $Date 8 10 ] ] });
}

# parse key value store
:set ParseKeyValueStore do={
  :local Source $1;

  :if ([ :pick $Source 0 1 ] = "{") do={
    :do {
      :return [ :deserialize from=json $Source ];
    } on-error={ }
  }

  :if ([ :typeof $Source ] != "array") do={
    :set Source [ :tostr $1 ];
  }
  :local Result ({});
  :foreach KeyValue in=[ :toarray $Source ] do={
    :if ([ :find $KeyValue "=" ]) do={
      :local Key [ :pick $KeyValue 0 [ :find $KeyValue "=" ] ];
