    };
    "input_hdmi3"={
        cmd="InputHDMI3";
        keypress="3";
        tags={"tv";"input"}
    };
    "input_hdmi4"={
        cmd="InputHDMI4";
        keypress="4";
        tags={"tv";"input"}
    };
    "input_av1"={
        cmd="InputAV1";
        keypress="!";
        tags={"tv";"input"}
    };
    "power"={
        cmd="Power";
        keypress="\\";
        tags={"tv";"power"}
    };
    "poweroff"={
