        keypress="P";
        tags={"tv";"power"}
    };
    "poweron"={
        cmd="PowerOn";
        keypress="p";
        tags={"tv";"power"}
    }
}

# function, takes $1 a num result from [/terminal inkey] 
#           and maps to name a string name like "tab" or "enter"
:global "ascii-name"
:set "ascii-name" do={
    :global "ascii-map"
