                :if ([:tostr $lv]="") do={:set lv "\"\""}
            }
            :if ([:typeof $k]="num") do={
                :set line ([$puttab $lvl] . "- $[:tostr $lv]")
            } else={
                :set line ([$puttab $lvl] . "$[:tostr $k]: $[:tostr $lv]")
            }
            :put "$line"
        }
    }
    :return [:nothing]
}

