:global tofloat do={
    :global tobase;
    :local i;
    :local d;
    :local ip6comp 1000
    if ($1~"-") do={
        :set ip6comp 1001
        :set $1 [pick $1 1 99]
    }
    :if ([typeof $1]~("num")) do={
        :set $i $1; 
