{
:put "
[graphviz engine=patchwork]
graph {
	layout=patchwork
  node [style=filled]
"
:foreach a in=[/ip/firewall/filter/print stats as-value] do={
  :local fontsize (3*1024)
  :local color "CornflowerBlue"
  :if (($a->"action")~"(drop|tcp-reset)") do={:set color "Firebrick"}
