    :local intYear  ([:tonum [:pick $input 7 11]] * 10000)
    :local intMonth ([:tonum ($arrMonths->[:pick $input 1 3])] * 100)
    :local intDay   [:tonum [:pick $input 4 6]]

    :return ($intYear + $intMonth + $intDay)
}

